const pago = $input.first().json;

// Solo procesar pagos aprobados
if(pago.status !== 'approved') return [];

const ref = pago.external_reference || '';
const parts = ref.split('|');
const email         = parts[0] || 'cliente';
const plan          = parts[1] || 'pro';
const nombre        = parts[2] || 'Mi Negocio';
const orgIdExistente = parts[3] || '';   // presente si es upgrade de trial

let orgId;
if(orgIdExistente && orgIdExistente.trim()) {
  // Upgrade de cuenta trial existente
  orgId = orgIdExistente.trim();
} else {
  // Nuevo usuario desde landing
  const base = email.split('@')[0]
    .replace(/[^a-z0-9]/gi, '-')
    .toLowerCase()
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 16);
  const suffix = Date.now().toString().slice(-4);
  orgId = `${base}-${suffix}`;
}

const password = orgIdExistente 
  ? null
  : Math.random().toString(36).slice(-8);

const planFinal = plan.includes('ia') ? 'pro-ia' : 'pro';

return [{ json: { 
  org_id: orgId, 
  password, 
  email, 
  nombre, 
  plan: planFinal,
  es_upgrade: !!orgIdExistente,
  pago_id: pago.id
} }];

const items = $input.all();
if(items.length === 0){
  return [{ json: { found: false, error: 'Credenciales incorrectas' } }];
}
return [{ json: { ...items[0].json, found: true } }];

const body = $input.first().json.body;
const email = (body.email || '').trim().toLowerCase();
const password = (body.password || '').trim();
const nombre = (body.nombre_negocio || 'Mi Negocio').trim();

if (!email || !password) {
  throw new Error('email y password son obligatorios');
}

const base = email.split('@')[0]
  .replace(/[^a-z0-9]/gi, '-')
  .toLowerCase()
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 16);

const suffix = Date.now().toString().slice(-5);
const org_id = `${base}-${suffix}`;

const crypto = require("crypto");
const api_key = crypto.randomBytes(32).toString("hex");
return [{ json: { api_key, org_id, password, nombre, email } }];

const pgRows = $input.all();
const prev = $('Genera org_id').first().json;

const row = pgRows.length > 0 ? pgRows[0].json : {};

return [{
  json: {
    ok: true,
    org_id: row.org_id || prev.org_id,
    nombre: row.nombre || prev.nombre,
    email: row.email || prev.email,
    password: prev.password
  }
}];

